import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

project_details = {
    "projectId": os.getenv("PROJECT_ID", "recently-completed-project"),
    "status": "completed",
    "materials": [
        {"materialId": material_id}
        for material_id in os.getenv("MATERIAL_IDS", "").split(",")
        if material_id.strip()
    ],
    "analysisFocus": ["quality-standards-compliance", "energy-efficiency"],
}

analysis_response = session.post(
    f"{BASE_URL}/projects/analyze",
    json=project_details,
)
analysis_response.raise_for_status()
analysis_result = analysis_response.json()

process_id = os.getenv("PROCESS_ID")
if not process_id:
    raise ValueError("Set PROCESS_ID to the ID of the ongoing chemical monitoring process.")

process_update_response = session.put(
    f"{BASE_URL}/process/{process_id}/update",
    json={
        "settings": {
            "analysisFocus": ["energy-efficiency"],
            "energyEfficiencyMonitoring": True,
        }
    },
)
process_update_response.raise_for_status()

insights_response = session.get(f"{BASE_URL}/insights/data")
insights_response.raise_for_status()
process_insights = insights_response.json()

logs_response = session.post(
    f"{BASE_URL}/logs/save",
    json={
        "processId": process_id,
        "data": process_insights,
        "projectAnalysis": analysis_result,
    },
)
logs_response.raise_for_status()

certifications_response = session.get(f"{BASE_URL}/certifications")
certifications_response.raise_for_status()
certifications = certifications_response.json()

print(
    {
        "projectAnalysis": analysis_result,
        "processInsights": process_insights,
        "certifications": certifications,
    }
)

import requests

BASE_URL = "https://api.socbench.example"

analytics_response = requests.post(
    f"{BASE_URL}/analytics/generate",
    json={"system": "supply chain", "reportType": "detailed"},
)
analytics_response.raise_for_status()
analytics = analytics_response.json()

components_response = requests.get(f"{BASE_URL}/components")
components_response.raise_for_status()
components = components_response.json()

# Select a component only when the analytics explicitly indicate it is no longer needed.
component_to_remove = None
for component in components:
    component_id = component.get("id")
    if component_id is None:
        continue

    if isinstance(analytics, dict):
        insights = analytics.get("insights", analytics.get("recommendations", []))
    else:
        insights = []

    for insight in insights if isinstance(insights, list) else []:
        if isinstance(insight, dict):
            insight_id = insight.get("componentId", insight.get("component_id"))
            recommendation = str(
                insight.get("recommendation", insight.get("status", ""))
            ).lower()
            if insight_id == component_id and any(
                phrase in recommendation
                for phrase in ("no longer needed", "remove", "decommission")
            ):
                component_to_remove = component_id
                break
    if component_to_remove is not None:
        break

if component_to_remove is not None:
    delete_response = requests.delete(
        f"{BASE_URL}/components/{component_to_remove}"
    )
    delete_response.raise_for_status()

