import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.getenv("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


# Start a network-wide vulnerability scan.
scan = request("POST", "/scan/network", json={})
scan_id = scan["scan_id"]

# Retrieve findings to inform resource updates and scaling policies.
findings = request("GET", f"/scan/{scan_id}/results")

# Update the resource configuration and properties using scan findings.
resource_id = os.environ["RESOURCE_ID"]
resource_update = {
    "configuration": {
        "vulnerability_scan_id": scan_id,
        "findings": findings,
        "remediation_status": "in_progress",
    },
    "properties": {
        "performance_optimization": True,
        "vulnerability_scan_id": scan_id,
    },
}
request("PATCH", f"/infrastructure/resources/{resource_id}", json=resource_update)

# Create a scaling policy that responds to the scan outcomes.
scaling_policy = {
    "name": "vulnerability-response-scaling",
    "conditions": {
        "scan_id": scan_id,
        "findings": findings,
    },
    "parameters": {
        "enabled": True,
        "adjustment": "dynamic",
    },
}
request("POST", "/scaling/policies", json=scaling_policy)

# Create a branch to track vulnerability remediation changes.
repository_id = os.environ["REPOSITORY_ID"]
branch_name = f"vulnerability-fixes-{scan_id}"
request(
    "POST",
    f"/repositories/{repository_id}/branches",
    json={
        "name": branch_name,
        "source_branch": os.getenv("SOURCE_BRANCH", "main"),
    },
)

# Register the application and configure access control for the updates.
application = {
    "name": os.getenv("APPLICATION_NAME", "vulnerability-remediation"),
    "scan_id": scan_id,
    "resource_id": resource_id,
}
request("POST", "/access-control", json={
    "application": application,
    "policy": {
        "allow": ["security:read", "resource:update"],
        "deny": [],
    },
})

