import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

sensor_id = os.getenv("SENSOR_ID", "sensor_001")
notification_method = os.getenv("NOTIFICATION_METHOD", "email")
start_date = os.getenv("START_DATE", "2026-01-01")
end_date = os.getenv("END_DATE", "2026-01-31")
outdated_alert_id = os.getenv("OUTDATED_ALERT_ID", "outdated-simulation-alert")

# Retrieve incident history and identify disruptions involving the specified sensor.
incidents_response = session.get(f"{BASE_URL}/incident-history")
incidents_response.raise_for_status()
incident_history = incidents_response.json()

def contains_sensor(value, target):
    if isinstance(value, dict):
        return any(
            target in str(key) or contains_sensor(item, target)
            for key, item in value.items()
        )
    if isinstance(value, list):
        return any(contains_sensor(item, target) for item in value)
    return target in str(value)

disruptions = [
    incident for incident in (
        incident_history if isinstance(incident_history, list)
        else incident_history.get("incidents", [])
    )
    if contains_sensor(incident, sensor_id)
]

# Verify the sensor's current functionality.
sensor_response = session.get(f"{BASE_URL}/status/{sensor_id}")
sensor_response.raise_for_status()
sensor_status = sensor_response.json()

# Fetch consumption trends for affected customers during the disruption period.
consumption_trends = []
for incident in disruptions:
    incident_data = incident if isinstance(incident, dict) else {}
    affected_customers = incident_data.get("affected_customers", [])
    if isinstance(affected_customers, int):
        affected_customers = incident_data.get("customer_ids", [])

    if isinstance(affected_customers, (str, int)):
        affected_customers = [affected_customers]

    for customer_id in affected_customers:
        params = {"customerId": customer_id, "startDate": start_date, "endDate": end_date}
        response = session.get(f"{BASE_URL}/consumption/summary", params=params)
        response.raise_for_status()
        consumption_trends.append({
            "customerId": customer_id,
            "incident": incident,
            "summary": response.json(),
        })

# Configure peak usage alerts for affected customers.
peak_alert_results = []
for customer_id in dict.fromkeys(
    item["customerId"] for item in consumption_trends
):
    response = session.post(
        f"{BASE_URL}/peak-alert",
        json={"customerId": customer_id, "notificationMethod": notification_method},
    )
    response.raise_for_status()
    peak_alert_results.append({
        "customerId": customer_id,
        "result": response.json() if response.content else None,
    })

# Remove the outdated incident-management alert setting.
delete_response = session.delete(
    f"{BASE_URL}/alert-settings/{outdated_alert_id}"
)
delete_response.raise_for_status()

results = {
    "disruptions": disruptions,
    "sensor_status": sensor_status,
    "consumption_trends": consumption_trends,
    "peak_alerts": peak_alert_results,
    "outdated_alert_deletion_status": delete_response.status_code,
}

